export type DateOnly = string;                     // "2024-04-01" - sortable, zone-free
export interface Version<T> { readonly effective: DateOnly; readonly value: T }

export function valueAt<T>(parts: readonly Version<T>[], when: DateOnly): T {
  const v = parts.findLast(p => p.effective <= when);      // short lists; binary search if long
  if (!v) throw new RangeError(`no value effective on ${when}`);
  return v.value;
}
export function put<T>(parts: Version<T>[], from: DateOnly, value: T): void {
  parts.push({ effective: from, value }); parts.sort((a, b) => a.effective.localeCompare(b.effective));
}
export const currentValue = <T>(parts: readonly Version<T>[]): T =>
  valueAt(parts, new Date().toISOString().slice(0, 10));   // inject this date in tests
